const tabId = 2017691689;
const queries = [
  "art classes workshops Grand Rapids MI adult beginner",
  "pottery class Grand Rapids MI drop in workshop",
  "craft workshop studio Grand Rapids MI"
];

const found = [];
for (const q of queries) {
  await tool.navigate({ tabId, url: `https://duckduckgo.com/?q=${encodeURIComponent(q)}` });
  await tool.wait_for({ tabId, condition: "selector_visible", value: "a[data-testid='result-title-a']", timeout_ms: 6000 });
  const res = await browserjs(tabId, () => {
    return Array.from(document.querySelectorAll("article")).map(a => ({
      title: a.querySelector("h2")?.textContent?.trim(),
      link: a.querySelector("a[data-testid='result-title-a']")?.href,
      snippet: a.querySelector("[data-result='snippet']")?.textContent?.trim()
    }));
  });
  found.push({ query: q, results: res });
}

console.log(JSON.stringify(found, null, 2).slice(0, 4000));

const items = [];
for (const f of found) {
  for (const r of f.results) {
    if (r.link && !items.some(i => i.link === r.link)) {
      items.push(r);
    }
  }
}
console.log(items);

