const tabId = 2017691689;

async function checkUrl(url) {
  try {
    await tool.navigate({ tabId, url });
    await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 8000 });
    const text = (await browser.read({ tabId, maxChars: 500 })).text;
    return { url, ok: true, snippet: text.slice(0, 150).replace(/\s+/g, ' ') };
  } catch (e) {
    return { url, ok: false, error: e.message };
  }
}

const checks = [
  await checkUrl("https://sprucedstudio.com/location/"),
  await checkUrl("https://themudroom.com/contact/"),
  await checkUrl("https://potterylanegr.com/about-us/"),
  await checkUrl("https://www.artmuseumgr.org/visit")
];

console.log(checks);

